        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastRound = history[history.length - 1];
            var results = lastRound.results || {};
            var finalSat = results.satisfaction || 0;
            var finalEquity = results.equityIndex || 0;
            var finalFiscal = results.fiscalHealth || 0;
            var finalDebt = results.debtToRevenue || 0;

            var composite = (finalSat / 100) * 0.35 + finalFiscal * 0.25 + finalEquity * 0.20 + (1 - Math.min(finalDebt, 200) / 200) * 0.10 + (finalEquity > 0.7 ? 0.10 : finalEquity > 0.5 ? 0.05 : 0);

            var performance = window.mySimulation.t('perf_needs_improvement');
            if (composite >= 0.70) performance = window.mySimulation.t('perf_excellent');
            else if (composite >= 0.55) performance = window.mySimulation.t('perf_good');
            else if (composite >= 0.40) performance = window.mySimulation.t('perf_average');

            var insights = [];
            if (finalSat >= 65) insights.push(window.mySimulation.t('insight_strong_satisfaction'));
            if (finalSat < 45) insights.push(window.mySimulation.t('insight_low_satisfaction'));
            if (finalEquity >= 0.75) insights.push(window.mySimulation.t('insight_excellent_equity'));
            if (finalEquity < 0.55) insights.push(window.mySimulation.t('insight_low_equity'));
            if (finalFiscal >= 0.70) insights.push(window.mySimulation.t('insight_healthy_fiscal'));
            if (finalFiscal < 0.40) insights.push(window.mySimulation.t('insight_fiscal_risk'));
            if (finalDebt > 150) insights.push(window.mySimulation.t('insight_debt_high'));

            return {
                finalSatisfaction: finalSat,
                finalEquity: finalEquity,
                finalFiscal: finalFiscal,
                finalDebtRatio: finalDebt,
                compositeScore: Math.round(composite * 100),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.debtToRevenue > 130) return window.mySimulation.t('hint_debt_high');
            if (results.satisfaction < 40) return window.mySimulation.t('hint_low_satisfaction');
            if (results.equityIndex < 0.50) return window.mySimulation.t('hint_low_equity');
            if (results.waterSat < 40) return window.mySimulation.t('hint_water_crisis');
            if (results.fiscalHealth < 0.40) return window.mySimulation.t('hint_fiscal_crisis');
            if (results.satisfaction >= 65 && results.fiscalHealth >= 0.65) return window.mySimulation.t('hint_good_balance');
            return null;
        }

